class Solution {
    public: vector<vector<int>> matrixBlockSum(vector<vector<int>>& mat,int k){
        int rows=mat.size(),columns=mat[0].size();
        vector<vector<int>> prefix(rows+1,vector<int>(columns+1)),answer(rows,vector<int>(columns));
        for(int r=0;r<rows;++r)for(int c=0;c<columns;++c)prefix[r+1][c+1]=mat[r][c]+prefix[r][c+1]+prefix[r+1][c]-prefix[r][c];
        for(int r=0;r<rows;++r)for(int c=0;c<columns;++c){
            int top=max(0,r-k),bottom=min(rows-1,r+k),left=max(0,c-k),right=min(columns-1,c+k);
            answer[r][c]=prefix[bottom+1][right+1]-prefix[top][right+1]-prefix[bottom+1][left]+prefix[top][left];
        }
        return answer;
    }
};
